/// <summary>
/// PricingAttribute of table <c>InventTable</c> field CommissionGroupId.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Product, GUPPricingAttributeSourceLevel::Line)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(InventTable, CommissionGroupId))]
internal class GUPPricingAttributeInventTableCommissionGroupId extends GUPPricingAttributeInventTable implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventTable, CommissionGroupId);
}

public Set getAllowedValuesWithDescription()
{
    var ret = new Set(Types::AnyType);

    InventTable         inventTable;
    CommissionItemGroup commissionItemGroup;

    while select CommissionGroupId from inventTable
        join Name from commissionItemGroup
        group by commissionItemGroup.GroupId, commissionItemGroup.Name
        where inventTable.CommissionGroupId == commissionItemGroup.GroupId
    {
        GUPPricingAttributeAllowedValuesObject valueObject =
            new GUPPricingAttributeAllowedValuesObject(commissionItemGroup.GroupId, commissionItemGroup.Name);
        ret.add(valueObject);
    }
    return ret;
}
